import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { useSelector, useDispatch } from 'react-redux';
import { fetchMoodEntries, fetchMoodStats, setCurrentPeriod } from '../redux/slices/moodSlice';
import './MoodTracker.css';

const MoodTracker = () => {
  const dispatch = useDispatch();
  const { entries, stats, isLoading, error } = useSelector(state => state.mood);
  const [periodFilter, setPeriodFilter] = useState('month');
  
  // Fetch mood data when component mounts
  useEffect(() => {
    dispatch(fetchMoodEntries());
    dispatch(fetchMoodStats(periodFilter));
  }, [dispatch, periodFilter]);
  
  // Handle period change
  const handlePeriodChange = (period) => {
    setPeriodFilter(period);
    dispatch(setCurrentPeriod(period));
    dispatch(fetchMoodStats(period));
  };
  
  // Map mood scores to descriptive labels
  const moodLabels = {
    1: 'Very Low',
    2: 'Low',
    3: 'Somewhat Low',
    4: 'Below Average',
    5: 'Average',
    6: 'Somewhat Good',
    7: 'Good',
    8: 'Very Good',
    9: 'Excellent',
    10: 'Perfect'
  };
  
  return (
    <div className="mood-tracker-page">
      <div className="container">
        <div className="page-header">
          <h1>Mood Tracker</h1>
          <Link to="/mood-tracker/new" className="btn btn-primary">
            Log New Mood
          </Link>
        </div>
        
        {error && (
          <div className="error-banner">
            {error}
          </div>
        )}
        
        {isLoading && entries.length === 0 ? (
          <div className="loading-state">
            <div className="loading-spinner"></div>
            <p>Loading your mood data...</p>
          </div>
        ) : entries.length === 0 ? (
          <div className="empty-state">
            <div className="empty-icon">📊</div>
            <h2>No Mood Entries Yet</h2>
            <p>Start tracking your mood to gain insights into your emotional patterns.</p>
            <Link to="/mood-tracker/new" className="btn btn-primary">
              Log Your First Mood
            </Link>
          </div>
        ) : (
          <div className="mood-content">
            <div className="mood-chart-container">
              <div className="chart-header">
                <h2>Your Mood Over Time</h2>
                <div className="period-filter">
                  <button 
                    className={`period-btn ${periodFilter === 'week' ? 'active' : ''}`}
                    onClick={() => handlePeriodChange('week')}
                  >
                    Week
                  </button>
                  <button 
                    className={`period-btn ${periodFilter === 'month' ? 'active' : ''}`}
                    onClick={() => handlePeriodChange('month')}
                  >
                    Month
                  </button>
                  <button 
                    className={`period-btn ${periodFilter === 'year' ? 'active' : ''}`}
                    onClick={() => handlePeriodChange('year')}
                  >
                    Year
                  </button>
                </div>
              </div>
              
              {stats && (
                <div className="mood-stats">
                  <div className="stat-box">
                    <span className="stat-label">Average Mood</span>
                    <span className="stat-value">{stats.average_mood.toFixed(1)}</span>
                  </div>
                  
                  {stats.average_energy !== null && (
                    <div className="stat-box">
                      <span className="stat-label">Energy</span>
                      <span className="stat-value">{stats.average_energy.toFixed(1)}</span>
                    </div>
                  )}
                  
                  {stats.average_stress !== null && (
                    <div className="stat-box">
                      <span className="stat-label">Stress</span>
                      <span className="stat-value">{stats.average_stress.toFixed(1)}</span>
                    </div>
                  )}
                  
                  {stats.average_sleep !== null && (
                    <div className="stat-box">
                      <span className="stat-label">Sleep</span>
                      <span className="stat-value">{stats.average_sleep.toFixed(1)}</span>
                    </div>
                  )}
                  
                  <div className="stat-box">
                    <span className="stat-label">Entries</span>
                    <span className="stat-value">{stats.entry_count}</span>
                  </div>
                </div>
              )}
              
              <div className="chart-placeholder">
                {/* In a real implementation, we'd render a chart using a library like Chart.js */}
                {stats && stats.mood_trend && stats.mood_trend.length > 0 ? (
                  "Mood trend chart would display here"
                ) : (
                  "Not enough data for chart visualization"
                )}
              </div>
            </div>
            
            <div className="mood-entries-list">
              <h2>Recent Entries</h2>
              {entries.map(entry => (
                <div key={entry.id} className="mood-entry-card">
                  <div className="mood-entry-header">
                    <div className="mood-score">
                      <span className="score-value">{entry.mood_score}</span>
                      <span className="score-label">{moodLabels[entry.mood_score]}</span>
                    </div>
                    <div className="entry-date">
                      {new Date(entry.recorded_at).toLocaleDateString()} at {new Date(entry.recorded_at).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}
                    </div>
                  </div>
                  {entry.notes && (
                    <div className="mood-notes">
                      <p>{entry.notes}</p>
                    </div>
                  )}
                  <div className="mood-factors">
                    {entry.energy_level && (
                      <div className="factor">
                        <span className="factor-label">Energy:</span>
                        <span className="factor-value">{entry.energy_level}/10</span>
                      </div>
                    )}
                    {entry.stress_level && (
                      <div className="factor">
                        <span className="factor-label">Stress:</span>
                        <span className="factor-value">{entry.stress_level}/10</span>
                      </div>
                    )}
                    {entry.sleep_quality && (
                      <div className="factor">
                        <span className="factor-label">Sleep:</span>
                        <span className="factor-value">{entry.sleep_quality}/10</span>
                      </div>
                    )}
                  </div>
                </div>
              ))}
              
              {entries.length > 5 && (
                <div className="view-all-entries">
                  <Link to="/mood-tracker/history" className="btn btn-secondary">
                    View All Entries
                  </Link>
                </div>
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default MoodTracker;
